"""Read-only dashboard for locally generated v0.3 research reports.

No invented metrics; requires a real JSON report from hyunoptic-study.
"""
from __future__ import annotations
import json
import math
import streamlit as st

st.set_page_config(page_title="HyunOptic | Study Results", page_icon="📊", layout="wide")
st.title("HyunOptic — Research Evaluation")
st.warning("Research only. Reader disagreement is not glaucoma ground truth. No clinical interpretation.")

st.markdown(
    "Upload a **local JSON file generated by `hyunoptic-study`** to view internal "
    "holdout metrics. This page contains no preloaded patient data or sample performance claims."
)
uploaded = st.file_uploader("Open local v0.3 study JSON", type=["json"])
if uploaded is None:
    st.info("No study results loaded. Run the v0.3 command on a lawfully obtained local PAPILA folder.")
    st.stop()

try:
    payload = json.load(uploaded)
    summary = payload["summary"]
    if summary["project"] != "HyunOptic" or summary["version"] != "0.3.0":
        raise ValueError("Expected HyunOptic v0.3 report")
    if summary.get("not_external_validation") is not True:
        raise ValueError("Unsupported report: missing internal-study disclaimer")
    evaluation = summary["evaluation"]
    holdout = evaluation["holdout"]
    validation = evaluation["validation"]
    scores = holdout["scores"]
except (KeyError, ValueError, TypeError, json.JSONDecodeError) as exc:
    st.error(f"Invalid research report: {exc}")
    st.stop()

st.caption("Source: user-supplied study report. Labels are inter-reader vCDR differences, not diagnoses.")
a, b, c, d = st.columns(4)
a.metric("Analyzed images", int(summary["n_analyzed"]))
b.metric("Holdout patients", int(holdout["n_patients"]))
c.metric("Holdout images", int(holdout["n_images"]))
d.metric("Skipped images", int(summary["n_skipped"]))

st.subheader("Holdout review-budget comparison")
st.caption("Fixed review capacity; precision and recall describe agreement-review prioritization only.")
dataset = []
for name, metrics in scores.items():
    dataset.append({
        "candidate score": name,
        "precision": float(metrics["precision_at_budget"]),
        "recall": None if metrics["recall_at_budget"] is None else float(metrics["recall_at_budget"]),
        "flagged": int(metrics["cases_reviewed"]),
        "high disagreement": int(metrics["n_discrepant"]),
    })
st.dataframe(dataset, use_container_width=True, hide_index=True)
st.bar_chart({item["candidate score"]: item["precision"] for item in dataset})
st.caption("Chart: precision among top-ranked cases; a higher number does not imply external validity.")

with st.expander("Validation and internal holdout cohorts"):
    st.json({
        split: {
            "n_images": int(evaluation[split]["n_images"]),
            "n_patients": int(evaluation[split]["n_patients"]),
            "positive_disagreement": int(evaluation[split]["scores"]["v02_q95"]["n_discrepant"]),
        } for split in ("validation","holdout")
    })
with st.expander("Paired patient-bootstrap and limitations"):
    st.json(summary["paired_holdout_bootstrap"])
    for caveat in summary.get("caveats", []):
        st.write("- " + str(caveat))
with st.expander("Reproducibility and protocol"):
    st.code(str(summary["protocol_sha256"]), language=None)
    st.json(summary["protocol_settings"])
    st.json(summary["development_only_unsupervised_scaling"])

st.divider()
st.caption("Do not publish an internal holdout result as external performance. "
           "Data and code licensing, reader-label uncertainty, and failure cases must be reviewed.")
